# Completa la línea marcada y compruébala con py check.
def fusion_rrf(listas, k=60):
    puntos = {}
    for lista in listas:
        for pos, doc in enumerate(lista):
            puntos[doc] = puntos.get(doc, 0)   # ← cambia esta línea: suma 1 / (k + pos + 1)
    return sorted(puntos, key=lambda d: (-puntos[d], d))

print(fusion_rrf([["a", "b", "c"], ["b", "c", "a"]]))   # ['b', 'a', 'c']
